import{_ as e,o as t,c as a,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-01-25","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-01-25","date":"2022-01-25T00:00:00.000Z","updated":"2022-02-02T00:00:00.000Z","tags":["Ceph","分布式存储","Orchestrator","超时机制","离线主机检测"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-01-25.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-01-25.md","lastUpdated":1780460162000}'),r={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-01-25.md"};function o(s,l,n,h,p,u){return t(),a("div",null,[...l[0]||(l[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><p><strong>议题一：SSH命令超时问题</strong></p><ul><li>讨论了在Ceph Orchestrator管理模块中，SSH命令（如<code>set volume</code>命令）挂起导致服务器循环永久挂起的问题。</li><li>提出了引入超时机制的必要性，并讨论了使用异步SSH库的超时选项和cephadm内置的超时参数。</li><li>决定尝试使用cephadm的超时参数，并设置一个较高的默认超时时间，同时提供配置选项。</li></ul></li><li><p><strong>议题二：离线主机检测</strong></p><ul><li>讨论了如何检测离线主机，特别是在有代理的情况下，可以通过发送快速消息来确认主机是否在线。</li><li>如果代理响应失败，将尝试重置连接并进行常规的主机检查。</li></ul></li></ul><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><p><strong>超时机制实施</strong></p><ul><li>使用cephadm的超时参数，设置一个默认的高超时时间（如20分钟），并在超时后发出健康警告。</li><li>提供配置选项，以便用户可以根据需要调整超时时间。</li></ul></li><li><p><strong>离线主机检测</strong></p><ul><li>在有代理的情况下，通过发送消息来快速检测主机是否在线。</li><li>如果代理响应失败，将重置连接并进行常规的主机检查。</li></ul></li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><p><strong>实施超时机制</strong></p><ul><li>测试cephadm的超时参数是否有效，并确保在超时后能发出健康警告。</li><li>提供文档和健康警告信息，指导用户如何调整超时时间。</li></ul></li><li><p><strong>优化离线主机检测</strong></p><ul><li>在有代理的情况下，实现通过发送消息来快速检测主机是否在线的机制。</li><li>考虑在未来的版本中进一步优化代理的功能，以减少对SSH的依赖。</li></ul></li><li><p><strong>文档和跟踪</strong></p><ul><li>更新相关文档，说明新的超时机制和离线主机检测方法。</li><li>在跟踪系统中记录这些改进，以便后续跟踪和维护。</li></ul></li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li><p><strong>代理功能扩展</strong></p><ul><li>讨论了代理功能的扩展，以便未来能够完全替代SSH，特别是在部署和管理节点方面。</li><li>提出了创建一个大型跟踪器，列出代理需要实现的所有功能，以实现与SSH的完全功能对等。</li></ul></li><li><p><strong>告别</strong></p><ul><li>Sebastian宣布这是他最后一次参加会议，感谢团队并祝愿大家成功。</li></ul></li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议讨论了超时问题和离线主机检测的解决方案，并决定实施cephadm的超时参数和代理的快速检测机制。同时，提出了未来代理功能扩展的计划，并记录了相关行动计划。</p>',11)])])}const _=e(r,[["render",o]]);export{c as __pageData,_ as default};
